function out_out = mfun_gfm_observer(meas_in, u_c_ab_in, u_c_zoh_ab_in, p)
%MFUN_GFM_OBSERVER Block Observer of the control system.
%   Observer of motulator. Generated by motulator_export from the MATLAB port of
%   motulator and called by the MATLAB Function block of the Simulink model, which adds
%   its folder to the MATLAB path. The parameters are the fields of the struct p (from
%   the mask, [] as NaN). The state is in persistent variables, of which each MATLAB
%   Function block has its own copy.
persistent self
if isempty(self)
    self = gfm_observer_init(p.u_nom, p.w_nom, p.L, p.alpha_o, p.T_s, p.R);
end
meas = gfm_measurements_unpack(meas_in);
u_c_ab = complex_in(u_c_ab_in);
u_c_zoh_ab = complex_in(u_c_zoh_ab_in);
out = gfm_observer_compute_output(self, u_c_zoh_ab, meas.i_c_ab);
% Voltage for the control laws (GridConverterControlSystem.get_feedback)
out.u_c = exp(-1i*out.theta_c)*u_c_ab;
out_out = gfm_feedbacks_pack(out);
self = gfm_observer_update(self, p.T_s, out);
end

function s = gfm_measurements_unpack(u)
%GFM_MEASUREMENTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_c_ab', complex(u(1), u(2)), ...
    'u_dc', u(3), ...
    'u_c_ab', complex(u(4), u(5)));
end

function y = gfm_feedbacks_pack(s)
%GFM_FEEDBACKS_PACK Signal vector of the struct s.
y = [ ...
    real(s.i_c);
    imag(s.i_c);
    real(s.u_c);
    imag(s.u_c);
    real(s.u_c_zoh);
    imag(s.u_c_zoh);
    real(s.v_c);
    imag(s.v_c);
    real(s.u_g);
    imag(s.u_g);
    s.p_g;
    s.q_g;
    s.theta_c;
    s.w_c];
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function theta = wrap(theta)
%WRAP Limit the angle into the range [-pi, pi), as numpy.mod does.
x = rem(theta + pi, 2*pi);
if x < 0
    x = x + 2*pi;
end
theta = x - pi;
end

function self = gfm_observer_init(u_nom, w_nom, L, alpha_o, T_s, R)
%GFM_OBSERVER_INIT Discrete-time disturbance observer (Observer), with the
%   coefficients of the hold-equivalent model and the observer gain.
phi = exp(-1i*w_nom*T_s);
gamma_g = (phi - 1)/(1i*w_nom*L);
self = struct('L', L, 'R', R, 'w_g', w_nom, 'phi', phi, 'gamma_c', T_s*phi/L, ...
    'gamma_g', gamma_g, 'k_o', (1 - exp(-alpha_o*T_s))/gamma_g, 'theta_c', 0, ...
    'u_g', complex(u_nom), 'i_c', complex(0));
end

function out = gfm_observer_compute_output(self, u_c_ab, i_c_ab)
%GFM_OBSERVER_COMPUTE_OUTPUT Feedback signals from the converter voltage of the
%   ongoing sampling period and the converter current in stationary coordinates
%   (the field u_c is zero, and u_dc is not included).
theta_c = self.theta_c;
% Measured values in synchronous coordinates
rot = exp(-1i*theta_c);
i_c = rot*i_c_ab;
u_c_zoh = rot*u_c_ab;
% Correct the predicted grid-voltage estimate
u_g = self.u_g + self.k_o*(i_c - self.i_c);
v_c = u_g + 1i*self.w_g*self.L*i_c;
% Active and reactive powers
s_g = 1.5*u_g*conj(i_c);
out = struct('i_c', i_c, 'u_c', complex(0), 'u_c_zoh', u_c_zoh, 'v_c', v_c, ...
    'u_g', u_g, 'p_g', real(s_g), 'q_g', imag(s_g), 'theta_c', theta_c, ...
    'w_c', self.w_g);
end

function self = gfm_observer_update(self, T_s, out)
%GFM_OBSERVER_UPDATE Predict the current, the grid voltage being constant in these
%   coordinates.
self.i_c = self.phi*out.i_c + self.gamma_c*out.u_c_zoh ...
    + self.gamma_g*(out.u_g + self.R*out.i_c);
self.u_g = out.u_g;
self.theta_c = wrap(self.theta_c + T_s*self.w_g);
end
